const p3=new THREE.Vector3();
const mats=new Map();
function mat(color,opts={}){const key=color+JSON.stringify(opts);if(!mats.has(key))mats.set(key,new THREE.MeshStandardMaterial({color,roughness:1,flatShading:true,...opts}));return mats.get(key)}
function mesh(g,m,x=0,y=0,z=0,parent=world){const o=new THREE.Mesh(g,typeof m==='number'?mat(m):m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function box(w,h,d,c,x=0,y=0,z=0,parent=world){return mesh(new THREE.BoxGeometry(w,h,d),c,x,y,z,parent)}
function ball(r,c,x=0,y=0,z=0,parent=world,detail=1){return mesh(new THREE.IcosahedronGeometry(r,detail),c,x,y,z,parent)}
function cyl(rt,rb,h,c,x=0,y=0,z=0,parent=world,n=8){return mesh(new THREE.CylinderGeometry(rt,rb,h,n),c,x,y,z,parent)}
function group(parent=world){const g=new THREE.Group();parent.add(g);return g}
function ring(r,color,x,y,z,parent=world){const o=mesh(new THREE.TorusGeometry(r,.025,5,40),mat(color,{transparent:true,opacity:.65}),x,y,z,parent);o.rotation.x=-Math.PI/2;o.castShadow=false;return o}

function setup(){
 scene=new THREE.Scene();scene.background=new THREE.Color(0xe4ead7);scene.fog=new THREE.Fog(0xe4ead7,58,110);
 renderer=new THREE.WebGLRenderer({canvas:$('#world'),antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.22;
 camera=new THREE.OrthographicCamera();ambient=new THREE.HemisphereLight(0xfff6d8,0x739175,2.1);scene.add(ambient);
 sun=new THREE.DirectionalLight(0xfff0c8,3.0);sun.position.set(-15,28,12);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-27,right:27,top:25,bottom:-25,near:1,far:75});sun.shadow.normalBias=.035;sun.shadow.bias=-.0001;sun.shadow.radius=4;scene.add(sun);
 world=new THREE.Group();scene.add(world);clock=new THREE.Clock();resize();makeWorld();bind();resetLevel(saved.unlocked,false);requestAnimationFrame(loop);
 setTimeout(()=>{$('#loading').style.opacity='0';setTimeout(()=>$('#loading').remove(),500);showIntro()},350);
}
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h);const ar=w/h;const span=(ar<1?35/ar:34)/zoom;camera.left=-span*ar/2;camera.right=span*ar/2;camera.top=span/2;camera.bottom=-span/2;camera.near=.1;camera.far=140;updateCamera();camera.updateProjectionMatrix()}
function updateCamera(){const radius=47;camera.position.set(Math.sin(yaw)*radius,viewTop?62:39,Math.cos(yaw)*radius);camera.lookAt(0,0,0)}

function makeWorld(){
 // A floating, layered woodland diorama; every visible object is real geometry.
 box(39,1.15,30,0x847c57,0,-1.17,0);box(39.5,.6,30.5,0xb2b58c,0,-.47,0);
 for(const side of [-1,1]){
  box(14.9,1.3,29.5,0xb4bc77,side*12.1,.18,0);box(14.9,.2,29.5,0xbccf8a,side*12.1,.9,0);
  for(let j=0;j<39;j++){const z=-14.5+j*.76;const x=side*(4.65+rand(-.22,.2));const o=ball(rand(.4,.75),[0xc3cfa0,0xc6c393,0xacba84][j%3],x,.53,z);o.scale.set(1,.55,1.1)}
 }
 // The sandy river bed and translucent low-poly water.
 box(9.2,.17,30,0xb6cab0,0,-.16,0);
 const geo=new THREE.PlaneGeometry(9.25,30,22,62);geo.rotateX(-Math.PI/2);waterBase=geo.attributes.position.array.slice();water=mesh(geo,mat(0x75beb7,{transparent:true,opacity:.86,roughness:.3,metalness:.07}),0,.33,0);water.castShadow=false;
 const foamMat=mat(0xdbf2d9,{transparent:true,opacity:.57});
 for(let i=0;i<65;i++){const f=box(rand(.15,.65),.018,rand(.5,1.6),foamMat,rand(-4.2,4.2),.42,rand(-15,15));f.castShadow=false;ripples.push(f)}
 for(let i=0;i<12;i++){const stone=ball(rand(.45,.95),0x869f92,rand(-3.8,3.8),.22,rand(-13.5,13.5));stone.scale.y=.4}
 for(let i=0;i<10;i++){const x=rand(-4,4),z=rand(-14,14);if(Math.abs(z)%6<1.3)continue;const lily=cyl(.33,.33,.025,0x779960,x,.43,z,world,8);lily.castShadow=false;if(i%3===0)ball(.1,0xf0dbbe,x,.5,z)}
 // Foreground stepped waterfall.
 for(let i=0;i<10;i++){const o=box(.85,1.4,.2,mat(0xa3d6c7,{transparent:true,opacity:.75}),-4.05+i*.9,-.35,15.03);o.castShadow=false;}
 // Winding sandy paths leading to the crossing and a home clearing.
 const pathMat=mat(0xd9d6a4);
 for(const side of [-1,1])for(let i=0;i<29;i++){const z=-13+i*.95,x=side*(7.3+.7*Math.sin(i*.4));const p=cyl(1.12,1.12,.026,pathMat,x,1.018,z,world,10);p.castShadow=false;}
 for(let lane of [-6,0,6])for(let side of [-1,1]){box(3.3,.027,1.7,0xdad4a0,side*6.05,1.025,lane);}
 // Trees frame the play area but never block the crossing.
 const trees=[[-11,-11],[-14,-10],[-17,-12],[-18,-7],[-12,-7],[-15,-5],[-18,-1],[-13,2],[-17,4],[-11,6],[-15,8],[-18,11],[-13,12],[-10,11],[10,-12],[13,-11],[17,-12],[18,-8],[13,-7],[16,-5],[18,-1],[15,3],[18,5],[11,8],[15,9],[18,12],[12,13],[-8,-12],[-9,13],[8,-13],[8,13]];
 trees.forEach(([x,z],i)=>makeTree(x+rand(-.5,.5),z+rand(-.4,.4),i%5===0?'pine':'round',.8+rand(0,.45),i));
 for(let i=0;i<160;i++){const side=i%2?-1:1;const x=side*rand(5.1,19),z=rand(-14,14);if(Math.abs(Math.abs(x)-7.4)<1||dist({x,z},{x:11,z:-2})<3)continue;const c=i%5===0?0xe1cf8c:[0x98b173,0xa7be79,0x7fa061][i%3];const tuft=group();tuft.position.set(x,1.03,z);for(let k=0;k<3;k++){const b=mesh(new THREE.ConeGeometry(.065,rand(.22,.45),3),c,rand(-.15,.15),.12,rand(-.15,.15),tuft);b.rotation.z=rand(-.35,.35)}if(i%7===0){cyl(.02,.02,.27,0x719552,x,1.15,z);const f=ball(.105,[0xeac773,0xf2d8b8,0xe6b6a8][i%3],x,1.35,z);f.castShadow=false}}
 for(let i=0;i<20;i++){const x=(i%2?-1:1)*rand(9,18),z=rand(-13,13);const bush=ball(rand(.35,.65),[0x839b60,0xa7b66e,0x78925b][i%3],x,1.2,z);bush.scale.y=.7}
 makeCabin(12,-1.6);makeCamp(-10,-3.1);
 // Gatherable loose timber and renewable stone piles.
 [[-6.7,4],[-9.2,1.7],[-8.7,-8.7],[-12.2,-1],[-10,8],[7.3,8.6]].forEach(([x,z])=>makeResource('wood',x,z));
 [[-9.8,5.1],[-7.4,-9.4],[9,4],[13,6.5]].forEach(([x,z])=>makeResource('stone',x,z));
 // Three distinct routes, with the north route exposed to more driftwood.
 [-6,0,6].forEach((z,j)=>{const bridge={z,index:j,parts:[],group:group()};bridges.push(bridge);bridge.label=label('0'+(j+1)+' · 待建木桥',new THREE.Vector3(0,1.55,z-1.1),'blue');for(let n=0;n<6;n++){const g=group(bridge.group);g.position.set(-4+n*1.6,1.03,z);const plate=box(1.45,.025,1.35,mat(0xe6ffe2,{transparent:true,opacity:.23}),0,0,0,g);plate.castShadow=false;for(const side of [-1,1]){const dash=box(.26,.035,.04,mat(0xf3fadd,{transparent:true,opacity:.72}),side*.48,.035,.62,g);dash.castShadow=false;}bridge.parts.push({built:false,strength:1,hp:100,max:100,mesh:null,ghost:g,x:-4+n*1.6,z})}makeSign(-5.4,z-1.25,j===0?'01':j===1?'02':'03');});
 marker=ring(.45,0xfff4aa,0,1.06,0);marker.visible=false;
 player=makeAnimal('beaver');world.add(player);player.position.set(-7.5,1.05,2.1);player.rotation.y=-.35;
 const selection=ring(.66,0xfff2b4,0,.015,0,player);selection.material.opacity=.85;
 for(let i=0;i<7;i++){const g=group();g.position.set(rand(-40,40),rand(15,21),rand(-28,25));for(let j=0;j<3;j++){const c=ball(rand(1.3,2.4),mat(0xffffff,{transparent:true,opacity:.45}),j*2,0,0,g);c.scale.set(1.3,.35,.7);c.castShadow=false}clouds.push(g)}
 label('林间营地',new THREE.Vector3(-10,2.8,-3.1),'');label('归家小径',new THREE.Vector3(10,2.1,2.2),'');
}
function makeTree(x,z,type,scale,i){const g=group();g.position.set(x,1,z);g.scale.setScalar(scale);cyl(.22,.36,2,0x846443,0,1,0,g);if(type==='pine'){for(let n=0;n<3;n++)mesh(new THREE.ConeGeometry(1.4-n*.27,2,7),[0x66875b,0x719366,0x86a171][n],0,2.0+n*.75,0,g)}else{const color=[0x9cae65,0x9db774,0x84a168,0xb5c37a][i%4];ball(1.5,color,0,2.7,0,g);ball(1.12,color,.7,2.5,.2,g);ball(.9,color,-.5,3.3,-.15,g)}foliage.push({mesh:g,base:scale,x,z,type,seed:i});if(x<0&&i%2===0)nodes.push({type:'tree',x,z,mesh:g,ready:0});return g}
function makeResource(type,x,z){const g=group();g.position.set(x,1.04,z);if(type==='wood'){for(let j=0;j<3;j++){const log=cyl(.13,.13,1.2,0x996b42,(j-1)*.27,.15+Math.floor(j/2)*.16,0,g);log.rotation.x=Math.PI/2;const end=cyl(.105,.105,.015,0xd9b97c,(j-1)*.27,.15+Math.floor(j/2)*.16,.61,g);end.rotation.x=Math.PI/2}}else{for(let j=0;j<4;j++){const o=ball(.25+Math.random()*.16,[0x949f91,0xaab0a1,0x83938a][j%3],rand(-.35,.35),.2,rand(-.3,.3),g);o.scale.y=.75}}nodes.push({type,x,z,mesh:g,ready:0});}
function makeSign(x,z,text){const g=group();g.position.set(x,1,z);cyl(.06,.06,.9,0x9b7b4e,0,.45,0,g);box(.8,.5,.12,0xc5a76d,0,.85,0,g);box(.39,.08,.14,0xf5eac3,0,.87,.01,g);box(.1,.22,.14,0xf5eac3,.2,.8,.01,g);g.rotation.y=-.15;}
function makeCabin(x,z){const g=group();g.position.set(x,1,z);box(3.4,.2,3.1,0xab9771,0,.1,0,g);box(2.7,1.75,2.5,0xbd955d,0,1,0,g);for(let i=0;i<5;i++){box(2.8,.055,2.6,0xa37b46,0,.4+i*.32,0,g)}const roof=mesh(new THREE.ConeGeometry(2.5,1.8,4),0x6c8264,0,2.6,0,g);roof.rotation.y=Math.PI/4;roof.scale.z=.85;box(.72,1.3,.15,0x5e6e4c,0,.78,1.29,g);ball(.065,0xe5ce7f,.23,.85,1.4,g);for(const xx of [-.9,.9]){box(.48,.48,.15,0xf1d996,xx,1.13,1.28,g);box(.05,.5,.18,0x8e7953,xx,1.13,1.3,g);box(.5,.05,.18,0x8e7953,xx,1.13,1.3,g)}box(.45,.8,.5,0x8e947c,.78,2.8,-.65,g);for(let n=0;n<3;n++)box(1.5,.14,1,0xc6b587,0,.07-n*.035,1.7+n*.3,g);for(const xx of [-2.3,2.3]){cyl(.065,.09,.7,0xa58f5b,xx,.4,2.3,g);cyl(.065,.09,.7,0xa58f5b,xx,.4,-1.7,g);box(.06,.12,4,0xb6a074,xx,.57,.3,g)}
}
function makeCamp(x,z){const g=group();g.position.set(x,1,z);const tent=mesh(new THREE.CylinderGeometry(0,1.65,1.7,4),0xdebe6c,0,.9,0,g);tent.rotation.y=Math.PI/4;tent.scale.z=1.2;box(.5,1,.04,0x6c6b4b,0,.6,1.22,g);for(let i=0;i<7;i++){const a=i/7*Math.PI*2;ball(.16,0x99a18b,2+Math.cos(a)*.55,.1,Math.sin(a)*.55,g)}for(let i=0;i<3;i++){const l=cyl(.12,.12,.8,0x8e6e45,2,.1,0,g);l.rotation.z=Math.PI/2;l.rotation.y=i*1.05}ball(.23,0xdcb354,2,.25,0,g);}

function makeAnimal(type){const g=new THREE.Group(),isB=type==='beaver';const sp=SPECIES[type];const c=isB?0x9c6c43:sp.color;const s=type==='bear'?1.25:type==='deer'?1.05:type==='rabbit'?.72:.85;g.scale.setScalar(s);
 const body=ball(.49,c,0,.51,0,g,2);body.scale.set(.78,1.1,1.08);g.userData.body=body;
 const head=ball(.38,c,0,1.08,-.25,g,2);head.scale.set(1,.93,.9);g.userData.head=head;
 const snout=ball(.22,isB?0xc4a16d:type==='fox'?0xffedd1:type==='rabbit'?0xf8e8d5:0xceab7d,0,.99,-.55,g);snout.scale.set(1,.75,.78);
 ball(.076,type==='rabbit'?0xb88178:0x393a2c,0,1.035,-.718,g);
 for(const side of [-1,1]){ball(.052,0x29382d,side*.185,1.16,-.548,g,1);ball(.017,0xfff9dc,side*.183-.01,1.18,-.59,g);}
 // Legs animate independently so carrying, walking and waiting remain readable.
 g.userData.legs=[];
 for(const side of [-1,1])for(const zz of [-.25,.25]){const leg=ball(.145,c,side*.24,.15,zz,g);leg.scale.set(.85,.95,1.35);g.userData.legs.push(leg)}
 if(type==='rabbit'){for(const side of [-1,1]){const ear=ball(.2,c,side*.19,1.54,-.19,g);ear.scale.set(.58,2.2,.56);const inner=ball(.13,0xcba5a0,side*.19,1.56,-.3,g);inner.scale.set(.45,2,.3)}ball(.17,0xf8eedd,0,.5,.54,g)}
 else if(type==='deer'){for(const side of [-1,1]){const ear=ball(.2,c,side*.38,1.25,-.23,g);ear.scale.set(1,.5,.5);const ant=cyl(.03,.055,.48,0x816744,side*.22,1.57,-.17,g);ant.rotation.z=side*-.25;const twig=cyl(.02,.03,.22,0x816744,side*.28,1.62,-.14,g);twig.rotation.z=side*.8}for(let i=0;i<6;i++)ball(.045,0xf3dbb3,(i%2?1:-1)*.38,.63+Math.floor(i/2)*.13,Math.floor(i/2)*.1,g)}
 else{for(const side of [-1,1]){if(type==='fox'){const ear=mesh(new THREE.ConeGeometry(.2,.4,4),c,side*.25,1.42,-.23,g);ear.rotation.z=side*-.18}else{ball(.13,c,side*.29,1.35,-.21,g);ball(.07,0x9f805e,side*.3,1.37,-.3,g)}}}
 if(isB){const tail=ball(.42,0x70513a,0,.18,.69,g);tail.scale.set(.8,.22,1.4);for(let i=-1;i<=1;i++){const line=box(.5,.012,.024,0x8b6947,0,.282,.63+i*.13,g);line.rotation.y=.5}for(const side of [-1,1])box(.1,.14,.065,0xfff3d2,side*.055,.88,-.72,g);const hat=cyl(.39,.39,.055,0xeac05c,0,1.38,-.26,g,12);const top=ball(.29,0xe4b24a,0,1.47,-.26,g);top.scale.y=.5;box(.48,.46,.24,0x7b915d,0,.64,.43,g);box(.54,.08,.26,0xa1b375,0,.86,.44,g);const scarf=box(.48,.08,.38,0x718c65,0,.9,-.18,g);}
 if(type==='fox'){const tail=ball(.35,c,0,.48,.67,g);tail.scale.set(.65,.75,1.5);ball(.18,0xf2dfba,0,.48,1.06,g)}
 g.userData.type=type;return g;
}

function label(text,pos,cls=''){const el=document.createElement('div');el.className='world-label '+cls;el.textContent=text;$('#worldLabels').appendChild(el);const l={el,pos};labels.push(l);return l}
function renderLabels(){for(const l of labels){const v=l.pos.clone().project(camera);l.el.style.left=(v.x*.5+.5)*innerWidth+'px';l.el.style.top=(-v.y*.5+.5)*innerHeight+'px';l.el.style.display=v.z>1?'none':''}}
function makeBridgePart(b,p){if(p.mesh)b.group.remove(p.mesh);const g=group(b.group);g.position.set(p.x,1.06,p.z);p.mesh=g;p.ghost.visible=false;for(let i=0;i<5;i++){const plank=box(.285,.16,1.52,i%2===0?0xcba365:0xb99057,(i-2)*.3,0,0,g);plank.rotation.z=rand(-.025,.025)}for(const zz of [-.55,.55]){box(1.62,.18,.17,0x886742,0,-.13,zz,g)}if(p.strength===2){for(const zz of [-.7,.7]){cyl(.1,.14,.95,0x867c5f,0,-.3,zz,g);box(1.64,.08,.085,0x8c845d,0,.42,zz,g);box(.1,.51,.1,0xc4ac73,0,.2,zz,g)}box(.23,.04,1.55,0x8e957d,0,.1,0,g)}g.scale.y=.1;}
function resetLevel(i,start=true){S.level=i;const l=LEVELS[i];Object.assign(S,{wood:l.wood,stone:l.stone,energy:100,time:l.time,rescued:0,elapsed:0,finished:false,target:null,pending:null,activeAnimal:null,washed:0,builds:0,repairs:0,cooldown:0,started:start,paused:!start,rain:i===2});keys.clear();for(const a of actors)world.remove(a.mesh);actors=[];for(const f of floating)world.remove(f.mesh);floating=[];for(const p of particles)world.remove(p.mesh);particles=[];
 for(const b of bridges)for(const p of b.parts){if(p.mesh)b.group.remove(p.mesh);Object.assign(p,{built:false,strength:1,hp:100,max:100,mesh:null});p.ghost.visible=true;}
 nodes.forEach(n=>{n.ready=0;n.mesh.visible=true;n.mesh.scale.setScalar(n.type==='tree'?foliage.find(t=>t.mesh===n.mesh)?.base||1:1)});
 l.animals.forEach((type,j)=>{const a=makeAnimal(type);a.position.set(-8.65-(j%2)*1.25,1.05,-5+(Math.floor(j/2))*1.65);a.rotation.y=-Math.PI/2;world.add(a);actors.push({type,mesh:a,state:'waiting',route:[],routeIndex:0,walk:0,id:j,waitPos:a.position.clone(),bridge:null})});
 player.position.set(-7.2,1.05,2.1);player.rotation.y=-.45;marker.visible=false;sun.color.set(i===3?0xffd796:0xfff0c8);sun.intensity=i===2?1.9:3;scene.background.set(i===2?0xd3dfd5:0xe4ead7);scene.fog.color.copy(scene.background);water.material.color.set(i>1?0x67aea9:0x75beb7);
 foliage.forEach((t,j)=>{if(t.type==='round')t.mesh.children.forEach(c=>{if(c.geometry.type==='IcosahedronGeometry')c.material=mat(i===3?[0xc8b268,0xd0a56b,0xa7ad65,0xb8bb71][j%4]:[0x9cae65,0x9db774,0x84a168,0xb5c37a][j%4])})});
 $('#chapter').textContent=`CHAPTER 0${i+1} / 04`;$('#levelTitle').textContent=l.name;$('#levelDesc').textContent=l.desc;$('#weather').textContent=l.weather;$('.location-label b').textContent=l.season;$('#total').textContent=actors.length;$('#animalQueue').innerHTML=actors.map(a=>`<span class="animal-chip" title="${SPECIES[a.type].name} · ${SPECIES[a.type].weight===2?'需要整桥加固':'可走木桥'}">${SPECIES[a.type].emoji}</span>`).join('');setMode('move');setHint(l.goal);updateUi();if(start)toast('第 '+(i+1)+' 站 · '+l.name);}
function setMode(m){S.mode=m;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));const hints={move:'点击地面前往目的地；WASD 移动，按住 Shift 冲刺。',gather:'点击木堆、树木或石堆，阿木会走过去采集。',build:'点击河上的虚线建桥：每段 2 木材，共 6 段。',reinforce:'点击木桥逐段加固：1 木材 + 1 石材，供小鹿和棕熊通行。',repair:'点击受损桥段修复：1 木材恢复全部耐久。'};setHint(hints[m]);}
function setHint(text){$('#hint p').textContent=text}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');toastUntil=performance.now()+3200;}
function updateUi(){ $('#wood').textContent=S.wood;$('#stone').textContent=S.stone;$('#coins').textContent=S.coins;$('#rescued').textContent=S.rescued;$('#progressFill').style.width=(S.rescued/actors.length*100)+'%';$('#energyFill').style.width=S.energy+'%';$('#timer').textContent=`${String(Math.floor(S.time/60)).padStart(2,'0')}:${String(Math.floor(S.time%60)).padStart(2,'0')}`;$('#timer').style.color=S.time<45?'#b7754c':'';$('#statusText').textContent=inWater(player.position)?'游泳中 · 水流会消耗精力':S.energy<30?'稍作休息，恢复精力':S.activeAnimal?'伙伴正在过桥，留意桥况':'精力充沛，开工吧！';actors.forEach((a,i)=>$('#animalQueue').children[i]?.classList.toggle('done',a.state==='saved'));$('#soundBtn .off-dot').style.display=saved.sound?'none':'';$('#soundBtn').setAttribute('aria-label',saved.sound?'关闭声音':'开启声音');for(const b of bridges){const built=b.parts.filter(p=>p.built),strong=built.filter(p=>p.strength===2).length;const hp=built.length?Math.round(Math.min(...built.map(p=>p.hp/p.max))*100):100;b.label.el.textContent='0'+(b.index+1)+' · '+(built.length===6?(strong===6?'加固桥':'木桥')+' · '+hp+'%':built.length+' / 6 桥段');b.label.el.classList.toggle('danger',hp<40);}}
function nearestNode(pos,range=2.25){let found=null,best=range;for(const n of nodes){if(n.ready>S.elapsed)continue;const d=dist(pos,n);if(d<best){best=d;found=n}}return found}
function nearestBridge(pos){return bridges.reduce((best,b)=>Math.abs(b.z-pos.z)<Math.abs(best.z-pos.z)?b:best,bridges[0])}
function onBridge(pos){for(const b of bridges)if(Math.abs(pos.z-b.z)<.83){const p=b.parts.find(p=>p.built&&Math.abs(pos.x-p.x)<.81);if(p)return p}return null}
function inWater(pos){return Math.abs(pos.x)<4.65&&!onBridge(pos)}
function gather(n=nearestNode(player.position)){if(!n){toast('靠近木堆、树木或石堆，再按 E 采集。');return false}if(n.ready>S.elapsed){toast('资源正在恢复，附近还有其他材料。');return false}if(dist(player.position,n)>2.5){setTarget({x:n.x,z:n.z},{type:'gather',node:n});return false}if(S.cooldown>0)return false;
 const amount=(n.type==='stone'?2:n.type==='tree'?3:4)+(n.type==='stone'?0:saved.upgrades.axe);if(n.type==='stone')S.stone+=amount;else S.wood+=amount;n.ready=S.elapsed+(n.type==='tree'?12:n.type==='stone'?14:18);if(n.type!=='tree')n.mesh.visible=false;else n.mesh.rotation.z=.08;S.cooldown=.4;S.energy=Math.max(0,S.energy-2);burst(n.x,1.8,n.z,n.type==='stone'?0xc8d1ba:0xe6c582,10);sound('gather');toast(`+${amount} ${n.type==='stone'?'石材':'木材'} · ${n.type==='tree'?'树木会再生枝条':'稍后可再次采集'}`);updateUi();return true;}
function actBridge(b,action,selected=null){let p=selected;if(action==='build')p=b.parts.find(p=>!p.built);else if(action==='reinforce')p=selected?.built&&selected.strength<2?selected:b.parts.find(p=>p.built&&p.strength<2);else p=selected?.built&&selected.hp<selected.max-1?selected:b.parts.filter(p=>p.built&&p.hp<p.max-1).sort((a,b)=>a.hp-b.hp)[0];
 if(!p){toast(action==='build'?'这座桥已经连通！按 F 护送伙伴。':action==='reinforce'?'已建桥段都已加固。':'这座桥状态很好，无需修复。');return false}
 // All worksites can be operated from the nearest bank or completed span.
 const bx=action==='build'?p.x-1.35:p.x;const approach={x:bx<-4.5?-5.15:bx,z:b.z};if(dist(player.position,approach)>2.4){setTarget(approach,{type:action,bridge:b,part:p});return false}if(S.cooldown>0)return false;
 if(action==='build'){if(S.wood<2){toast('还需要 2 木材。去左岸采集一些吧。');return false}S.wood-=2;p.built=true;p.strength=1;p.max=100+saved.upgrades.craft*30;p.hp=p.max;S.builds++;makeBridgePart(b,p);sound('build');burst(p.x,1.2,p.z,0xf4cf76,12);if(b.parts.every(p=>p.built)){toast('木桥连通了！按 F 邀请下一位伙伴过河。');setHint('桥通啦！按 F 护送；小鹿和棕熊需要整座桥都加固。');sound('success')}else toast(`搭好了！${b.parts.filter(p=>p.built).length} / 6 桥段 · −2 木材`)}
 else if(action==='reinforce'){if(S.wood<1||S.stone<1){toast('加固需要 1 木材 + 1 石材。');return false}S.wood--;S.stone--;p.strength=2;p.max=185+saved.upgrades.craft*35;p.hp=p.max;makeBridgePart(b,p);burst(p.x,1.3,p.z,0xc7d5b3,10);sound('build');toast('桥段已加固 · 耐久提高，可承载大型动物。')}
 else {if(S.wood<1){toast('修桥需要 1 木材。');return false}S.wood--;p.hp=p.max;S.repairs++;burst(p.x,1.3,p.z,0xbcd995,8);sound('build');toast('桥段焕然一新！−1 木材')}
 S.cooldown=.25;updateUi();return true;
}
function interact(){if(S.paused||S.finished)return;const n=nearestNode(player.position);if(n){gather(n);return}const b=nearestBridge(player.position);if(Math.abs(player.position.z-b.z)<2.2&&Math.abs(player.position.x)<7){actBridge(b,S.mode==='reinforce'?'reinforce':S.mode==='repair'?'repair':'build');return}toast('走近材料按 E，或切换工具后点击场景。')}
function setTarget(pos,pending=null){S.target={x:clamp(pos.x,-18.4,18.4),z:clamp(pos.z,-13.8,13.8)};S.pending=pending;marker.position.set(S.target.x,1.08,S.target.z);marker.visible=true;}
function escort(){if(S.paused||S.finished)return false;if(S.activeAnimal){toast('一位伙伴正在过河，先护送它到家。');return false}const a=actors.find(a=>a.state==='waiting');if(!a)return false;const sp=SPECIES[a.type];const complete=bridges.filter(b=>b.parts.every(p=>p.built));if(!complete.length){toast('先搭通一座桥：点击虚线，连续建造 6 段。');setMode('build');return false}const sturdy=complete.filter(b=>b.parts.every(p=>p.strength>=sp.weight));if(!sturdy.length){toast('这位伙伴比较重，需要一座全部加固的桥。');setMode('reinforce');return false}const valid=sturdy.filter(b=>b.parts.every(p=>p.hp>12));if(!valid.length){toast('桥梁受损严重，请先修复。');setMode('repair');return false}const b=valid.sort((x,y)=>Math.abs(x.z-a.mesh.position.z)-Math.abs(y.z-a.mesh.position.z))[0];a.bridge=b;a.state='crossing';a.route=[{x:-6,z:b.z},{x:-4.5,z:b.z},{x:5.5,z:b.z},{x:9.5+rand(-.5,.5),z:2.5+rand(-1,1)}];a.routeIndex=0;S.activeAnimal=a;toast(`${sp.emoji} ${sp.name}出发了！守好它脚下的桥。`);sound('whistle');return true;}
function animalSaved(a){a.state='saved';a.bridge=null;S.activeAnimal=null;S.rescued++;S.coins+=SPECIES[a.type].reward;burst(a.mesh.position.x,2,a.mesh.position.z,0xf6cd6a,25);sound('success');save();toast(`${SPECIES[a.type].name}到家了！+${SPECIES[a.type].reward} 橡果币`);updateUi();if(S.rescued===actors.length)completeLevel();else setHint('伙伴平安到达！检查桥况后按 F 继续护送。')}
function resetAnimal(a){a.mesh.position.copy(a.waitPos);a.state='waiting';a.bridge=null;a.route=[];S.activeAnimal=null;toast('桥断了！伙伴已退回安全岸边，补好桥就能再出发。');sound('warn')}
function damagePart(p,amount){if(!p.built)return;p.hp=Math.max(0,p.hp-amount);if(p.hp<=0){p.built=false;if(p.mesh)p.mesh.parent.remove(p.mesh);p.mesh=null;p.ghost.visible=true;burst(p.x,.65,p.z,0xbf996a,16);if(S.activeAnimal?.bridge?.parts.includes(p))resetAnimal(S.activeAnimal);else toast('漂木撞坏了一段桥，重新补上就好。');}else if(p.mesh){p.mesh.children.forEach(m=>{if(m.geometry.type==='BoxGeometry')m.rotation.z=Math.sin(S.anim*4)*(.015+Math.max(0,.5-p.hp/p.max)*.03)})}}
function completeLevel(){S.finished=true;S.paused=true;const stars=(S.time>LEVELS[S.level].time*.5?1:0)+(S.washed===0?1:0)+1;const first=saved.stars[S.level]===0;const reward=stars*6+(first?8:0);S.coins+=reward;saved.stars[S.level]=Math.max(saved.stars[S.level],stars);saved.unlocked=Math.min(3,Math.max(saved.unlocked,S.level+1));save();confetti();showModal(`<span class="eyebrow">${S.level===3?'THE FOREST IS TOGETHER AGAIN':'A LITTLE BRIDGE, A BIG DIFFERENCE'}</span><div class="big-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><h2>${S.level===3?'大家，都到家了。':'这条回家的路，有你真好。'}</h2><p>${S.level===3?'你完成了森林的全部四段旅程。再走一遍，试着收集每一颗星星吧。':'溪谷的伙伴记住了你的名字。带上橡果，继续下一段旅程。'}</p><div class="stats-grid"><div class="stat-tile"><strong>${S.rescued}</strong><span>伙伴平安到家</span></div><div class="stat-tile"><strong>${Math.floor(S.elapsed)}s</strong><span>本次用时</span></div><div class="stat-tile"><strong>+${reward}</strong><span>额外橡果奖励</span></div></div><p class="small-note">星星目标：全部护送 · 用时不到一半 · 没有精力耗尽</p><div class="modal-actions"><button class="primary" id="nextLevelBtn">${S.level<3?'前往下一站 →':'再游溪谷 →'}</button><button class="secondary" id="resultUpgrade">升级装备</button></div>`,'result');$('#nextLevelBtn').onclick=()=>{closeModal();resetLevel(S.level<3?S.level+1:0)};$('#resultUpgrade').onclick=()=>showUpgrades(true)}
function failLevel(){S.finished=true;S.paused=true;showModal(`<span class="eyebrow">TAKE A BREATH</span><span class="intro-illustration">🌙</span><h2>天黑了，明天再试一次。</h2><p>已经送回家的伙伴都很感谢你。先集中材料搭通一条路线，再依次护送；大型动物需要全桥加固。</p><div class="modal-actions"><button class="primary" id="retryBtn">重新挑战这关</button><button class="secondary" id="failMapBtn">查看旅程</button></div>`,'result');$('#retryBtn').onclick=()=>{closeModal();resetLevel(S.level)};$('#failMapBtn').onclick=showMap;}
function confetti(){for(let i=0;i<45;i++){const p=document.createElement('i');p.className='confetti';p.style.left=rand(10,90)+'%';p.style.top=rand(5,25)+'%';p.style.background=['#e7bd5c','#8fa766','#f5e5b7','#bb8260'][i%4];p.style.animationDelay=rand(0,.5)+'s';document.body.appendChild(p);setTimeout(()=>p.remove(),3200)}}

let modalReturn=null,focusBefore=null;
function showModal(html,type='help'){if(!S.modal){focusBefore=document.activeElement;modalReturn=S.paused}S.modal=type;S.paused=true;keys.clear();$('#modal').innerHTML=html;const heading=$('#modal h2');if(heading)heading.id='modalTitle';$('#modalBackdrop').classList.remove('hidden');requestAnimationFrame(()=>$('#modal button')?.focus());}
function closeModal(){S.modal=null;$('#modalBackdrop').classList.add('hidden');S.paused=S.finished||!S.started;focusBefore?.focus?.();updateUi();}
function dismissModal(){if(!S.started){showIntro();return}if(S.finished){const won=S.rescued===actors.length;showModal(`<span class="eyebrow">THE WOODLAND JOURNEY</span><h2>${won?'这一站的伙伴都到家了。':'休息好了，再试一次。'}</h2><p>${won?'你的星星和奖励都已保存，继续下一段旅程吧。':'集中资源搭好一座桥，逐一护送伙伴过河。'}</p><div class="modal-actions"><button class="primary" id="returnJourney">${won?'继续旅程 →':'重新挑战'}</button><button class="secondary" id="returnMap">选择关卡</button></div>`,'result');$('#returnJourney').onclick=()=>{closeModal();resetLevel(won?(S.level<3?S.level+1:0):S.level)};$('#returnMap').onclick=showMap;return}closeModal();}
function showIntro(){showModal(`<span class="eyebrow">WELCOME TO BEAVER CREEK</span><span class="intro-illustration">🦫</span><h2>嗨，我是阿木。</h2><p>一场涨水，隔开了森林里的朋友。一起捡起木材，搭好小桥，让每一位伙伴平安回家。</p><div class="guide-grid"><div class="guide-item"><b>① 收集森林的礼物</b><p>WASD 或点击地面移动。走近木材与石头，按 E 采集。</p></div><div class="guide-item"><b>② 一段一段搭起桥</b><p>选择「搭桥」，点击河中虚线。6 段木桥需要 12 木材。</p></div><div class="guide-item"><b>③ 邀请伙伴过河</b><p>按 F 开始护送。小鹿和棕熊需要整座桥都加固。</p></div><div class="guide-item"><b>④ 做个机灵的工匠</b><p>急流会损伤桥梁。采集、修桥、升级，挑战四段旅程。</p></div></div><div class="modal-actions"><button class="primary" id="startBtn">${saved.unlocked?'继续溪谷旅程':'开始第一段旅程'} →</button><button class="secondary" id="introMapBtn">选择关卡</button></div><p class="small-note">进度自动保存在当前浏览器 · 手机上可用方向键与点击操作</p>`,'intro');$('#startBtn').onclick=()=>{closeModal();resetLevel(saved.unlocked);sound('start')};$('#introMapBtn').onclick=showMap;}
function showHelp(){showModal(`<button class="modal-close" aria-label="关闭">×</button><span class="eyebrow">A WOODLAND FIELD GUIDE</span><h2>小海狸的工匠手册</h2><div class="guide-grid"><div class="guide-item"><b>走动与采集</b><p>WASD / 方向键移动，Shift 冲刺。E 采集。木堆 +4、树木 +3、石堆 +2，采完会再生。</p></div><div class="guide-item"><b>建造与养护</b><p>B 在最近路线建下一段，或选择工具点击。木桥 2 木材；加固 1 木 + 1 石；R 修复消耗 1 木。</p></div><div class="guide-item"><b>护送森林伙伴</b><p>F 邀请一只动物出发。兔子、狐狸能走木桥。小鹿、棕熊需要 6 段全部加固。</p></div><div class="guide-item"><b>水流与体力</b><p>海狸能游泳，但急流耗费精力。耗尽会回到营地并掉落 2 木材。桥断时动物安全返回起点。</p></div><div class="guide-item"><b>更灵巧的装备</b><p>护送可赚取橡果币。工匠小屋可升级采集、移动速度和桥梁耐久，升级跨关保留。</p></div><div class="guide-item"><b>星星与视角</b><p>全部救援、在一半时间内通关、没有耗尽精力，各得一星。滚轮缩放，拖动旋转，V 切换俯视。</p></div></div><p class="small-note">Esc 暂停 · 1–5 切换工具 · H 打开手册 · 切出页面时自动暂停</p><div class="modal-actions"><button class="primary" id="helpClose">明白了，回到溪谷</button></div>`,'help');$('.modal-close').onclick=closeModal;$('#helpClose').onclick=closeModal;}
function showPause(){if(S.finished||S.modal)return;showModal(`<button class="modal-close" aria-label="关闭">×</button><span class="eyebrow">A MOMENT IN THE WOODS</span><span class="intro-illustration">🍃</span><h2>让溪谷等一会儿。</h2><p>喝口水，歇歇脚。伙伴们都在安全的地方等你。</p><div class="modal-actions"><button class="primary" id="resumeBtn">继续旅程 →</button><button class="secondary" id="restartBtn">重新开始本关</button><button class="secondary" id="pauseMap">选择关卡</button></div>`,'pause');$('.modal-close').onclick=closeModal;$('#resumeBtn').onclick=closeModal;$('#restartBtn').onclick=()=>{closeModal();resetLevel(S.level)};$('#pauseMap').onclick=showMap;}
function showMap(){showModal(`<button class="modal-close" aria-label="关闭">×</button><span class="eyebrow">FOUR CHAPTERS, ONE FOREST</span><h2>我们的溪谷旅程</h2><p>循着水声，一站一站把森林重新连起来。</p>${LEVELS.map((l,i)=>`<div class="level-row"><span class="level-number">0${i+1}</span><div><b>${l.name}</b><p>${l.animals.length} 位伙伴 · ${l.weather}</p></div><span class="level-stars">${'★'.repeat(saved.stars[i])}${'☆'.repeat(3-saved.stars[i])}</span><button class="${i<=saved.unlocked?'primary':'secondary'}" data-level="${i}" ${i>saved.unlocked?'disabled':''}>${i>saved.unlocked?'未解锁':'出发'}</button></div>`).join('')}<p class="small-note">完成前一关即可解锁下一段旅程。装备和星星会保存在当前浏览器。</p>`,'map');$('.modal-close').onclick=dismissModal;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{closeModal();resetLevel(Number(b.dataset.level))});}
const UPGRADES={axe:{name:'利齿工匠',icon:'⚒',desc:'每次木材采集额外 +1',cost:[8,16]},boots:{name:'轻快脚掌',icon:'↝',desc:'移动速度 +15%，游泳更省力',cost:[7,14]},craft:{name:'结实木工',icon:'⬡',desc:'新建桥段耐久 +30，加固段 +35',cost:[10,18]}};
function showUpgrades(fromResult=false){const finished=S.finished;showModal(`<button class="modal-close" aria-label="关闭">×</button><span class="eyebrow">THE LITTLE WORKSHOP</span><h2>好工匠，也需要好装备。</h2><p>用伙伴送来的橡果，让下一段旅程轻松一些。</p><div style="color:#bb903b;font-weight:700;margin:18px 0">✦ <span id="shopCoins">${S.coins}</span> 橡果币</div>${Object.entries(UPGRADES).map(([k,u])=>{const lv=saved.upgrades[k];return `<div class="upgrade-row"><span class="upgrade-icon">${u.icon}</span><div><b>${u.name} <span style="color:#9aab83">${'●'.repeat(lv)}${'○'.repeat(2-lv)}</span></b><p>${u.desc}</p></div><button class="primary" data-upgrade="${k}" ${lv>=2||S.coins<u.cost[lv]?'disabled':''}>${lv>=2?'已满级':u.cost[lv]+' ✦'}</button></div>`}).join('')}<p class="small-note">升级跨关保留；耐久升级也会立即提高已建桥梁的耐久上限。</p><div class="modal-actions"><button class="primary" id="shopDone">${finished?(S.level<3?'前往下一站 →':'重游溪谷 →'):'回到溪谷'}</button></div>`,'shop');$('.modal-close').onclick=dismissModal;$('#shopDone').onclick=()=>{closeModal();if(finished)resetLevel(S.level<3?S.level+1:0)};document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const k=b.dataset.upgrade,lv=saved.upgrades[k],cost=UPGRADES[k].cost[lv];if(lv>=2||S.coins<cost)return;S.coins-=cost;saved.upgrades[k]++;if(k==='craft')bridges.forEach(br=>br.parts.forEach(p=>{if(p.built){const add=p.strength===2?35:30;p.max+=add;p.hp+=add}}));save();sound('success');updateUi();showUpgrades(fromResult)});}

function burst(x,y,z,color,count=8){for(let i=0;i<count;i++){const m=box(rand(.04,.12),rand(.04,.12),rand(.04,.12),color,x,y,z);m.castShadow=false;particles.push({mesh:m,v:new THREE.Vector3(rand(-1.6,1.6),rand(1,3),rand(-1.6,1.6)),life:rand(.5,1.15),max:1.15})}}
function spawnLog(){const x=rand(-3.9,3.9),g=group();g.position.set(x,.55,-15);const l=cyl(.15,.18,1.8,0x997544,0,0,0,g);l.rotation.z=Math.PI/2;for(const side of [-1,1]){const e=cyl(.12,.12,.02,0xd8bd85,side*.91,0,0,g);e.rotation.z=Math.PI/2}g.rotation.y=rand(-.4,.4);floating.push({mesh:g,speed:1+LEVELS[S.level].flow*2,hit:new Set()});}
function animatePlayer(dt,moving){const phase=S.anim*(moving?13:2);player.userData.body.rotation.z=moving?Math.sin(phase)*.045:Math.sin(phase)*.012;player.userData.head.rotation.z=Math.sin(S.anim*1.8)*.035;player.userData.legs.forEach((leg,i)=>{leg.position.y=.15+(moving?Math.max(0,Math.sin(phase+i%2*Math.PI+Math.floor(i/2)*Math.PI))*.15:0)});}
function movePlayer(dt){let dx=0,dz=0;const forward=keys.has('w')||keys.has('arrowup'),back=keys.has('s')||keys.has('arrowdown'),left=keys.has('a')||keys.has('arrowleft'),right=keys.has('d')||keys.has('arrowright');
 if(forward||back||left||right){const xx=(right?1:0)-(left?1:0),zz=(back?1:0)-(forward?1:0);dx=xx*Math.cos(yaw)+zz*Math.sin(yaw);dz=-xx*Math.sin(yaw)+zz*Math.cos(yaw);S.target=null;S.pending=null;marker.visible=false}
 else if(S.target){const d=dist(player.position,S.target);if(d>.18){dx=(S.target.x-player.position.x)/d;dz=(S.target.z-player.position.z)/d;}else{S.target=null;marker.visible=false;if(S.pending){const p=S.pending;S.pending=null;if(p.type==='gather')gather(p.node);else actBridge(p.bridge,p.type,p.part)}}}
 const len=Math.hypot(dx,dz);const swimming=inWater(player.position);const sprint=keys.has('shift')&&S.energy>8&&len>0;let speed=(3.5+saved.upgrades.boots*.53)*(swimming?.58:1)*(sprint?1.65:1);if(len>0){dx/=len;dz/=len;player.position.x=clamp(player.position.x+dx*speed*dt,-18.3,18.3);player.position.z=clamp(player.position.z+dz*speed*dt,-13.8,13.8);let angle=Math.atan2(-dx,-dz);let delta=angle-player.rotation.y;while(delta>Math.PI)delta-=Math.PI*2;while(delta<-Math.PI)delta+=Math.PI*2;player.rotation.y+=delta*Math.min(dt*12,1);}
 if(swimming){S.energy-=dt*(9+LEVELS[S.level].flow*5)/(1+saved.upgrades.boots*.18);player.position.z=clamp(player.position.z+LEVELS[S.level].flow*.75*dt,-13.8,13.8);player.position.y=.4+Math.sin(S.anim*6)*.06;if(Math.random()<dt*5)burst(player.position.x,.5,player.position.z,0xd6f5d7,1)}else{S.energy=clamp(S.energy+dt*(sprint?-9:9),0,100);player.position.y=1.05+(len>0?Math.abs(Math.sin(S.anim*10))*.035:0)}
 if(S.energy<=0){player.position.set(-7,1.05,2);S.energy=65;S.wood=Math.max(0,S.wood-2);S.target=null;S.pending=null;marker.visible=false;S.washed++;burst(-7,1.2,2,0xd7ecdb,18);toast('水流太急了！回营地休息，掉落了 2 木材。');sound('warn')}
 animatePlayer(dt,len>0);
 const n=nearestNode(player.position);const b=nearestBridge(player.position);let txt=null;if(n)txt=`${n.type==='stone'?'采集石材':n.type==='tree'?'啃下树枝':'拾取木材'}`;else if(Math.abs(player.position.x)<7&&Math.abs(player.position.z-b.z)<1.6)txt=S.mode==='reinforce'?'加固桥段':S.mode==='repair'?'修复桥段':'搭建下一段';
 const context=$('#context');context.classList.toggle('hidden',!txt||S.modal!=null);if(txt){context.querySelector('span').textContent=txt;const v=player.position.clone().add(new THREE.Vector3(0,2.45,0)).project(camera);context.style.left=(v.x*.5+.5)*innerWidth+'px';context.style.top=(-v.y*.5+.5)*innerHeight+'px';}
}
function moveAnimals(dt){for(const a of actors){if(a.state==='crossing'){if(!a.bridge.parts.every(p=>p.built)){resetAnimal(a);continue}const target=a.route[a.routeIndex],d=dist(a.mesh.position,target);if(d<.13){a.routeIndex++;if(a.routeIndex>=a.route.length){animalSaved(a);continue}}else{const sp=SPECIES[a.type],step=Math.min(d,dt*sp.speed);const dx=(target.x-a.mesh.position.x)/d,dz=(target.z-a.mesh.position.z)/d;a.mesh.position.x+=dx*step;a.mesh.position.z+=dz*step;a.mesh.rotation.y=Math.atan2(-dx,-dz);a.mesh.position.y=1.05+Math.abs(Math.sin(S.anim*sp.speed*4))*.055;const p=onBridge(a.mesh.position);if(p){damagePart(p,dt*(sp.weight*1.5+LEVELS[S.level].flow*2)/(p.strength===2?1.5:1));if(a.state!=='crossing')continue;}a.mesh.userData.legs.forEach((l,i)=>l.position.y=.15+Math.max(0,Math.sin(S.anim*12+i*Math.PI*.6))*.13);}}
 else{a.mesh.userData.head.rotation.y=Math.sin(S.anim*1.4+a.id)*.12;a.mesh.userData.body.scale.y=1.1+Math.sin(S.anim*2+a.id)*.015;if(a.state==='saved'){a.mesh.rotation.y=Math.sin(S.anim*.4+a.id)*.3-Math.PI/2}}
 }}
function simulate(dt){S.elapsed+=dt;S.time=Math.max(0,S.time-dt);S.cooldown=Math.max(0,S.cooldown-dt);movePlayer(dt);moveAnimals(dt);
 for(const n of nodes){if(n.ready<=S.elapsed&&!n.mesh.visible)n.mesh.visible=true;if(n.type==='tree')n.mesh.rotation.z*=.92;}
 for(const b of bridges)for(const p of b.parts){if(p.built){if(p.mesh){p.mesh.scale.y=Math.min(1,p.mesh.scale.y+dt*5);p.mesh.rotation.z=p.hp<p.max*.35?Math.sin(S.anim*3)*.015:0;} // Only storms erode idle bridges, gently enough to leave time for repairs.
 if(S.level>1)damagePart(p,dt*LEVELS[S.level].flow*(p.strength===2?.09:.22));}}
 if(Math.random()<dt*(S.level===0?.02:.045+S.level*.018))spawnLog();
 for(let i=floating.length-1;i>=0;i--){const f=floating[i];f.mesh.position.z+=f.speed*dt;f.mesh.position.y=.53+Math.sin(S.anim*3+i)*.035;for(const b of bridges){if(Math.abs(f.mesh.position.z-b.z)<.25&&!f.hit.has(b.index)){f.hit.add(b.index);const p=b.parts.find(p=>p.built&&Math.abs(p.x-f.mesh.position.x)<.8);if(p){damagePart(p,p.strength===2?7:21);burst(f.mesh.position.x,.7,b.z,0xe4ead5,12);world.remove(f.mesh);floating.splice(i,1);break}}}if(f.mesh.parent&&f.mesh.position.z>15){world.remove(f.mesh);floating.splice(i,1)}}
 if(S.time<=0&&!S.finished)failLevel();}
function loop(){requestAnimationFrame(loop);const dt=Math.min(clock.getDelta(),.05);S.anim+=dt;if(S.started&&!S.paused&&!S.finished)simulate(dt);else if(player)animatePlayer(dt,false);
 const arr=water.geometry.attributes.position.array;for(let i=0;i<arr.length;i+=3)arr[i+1]=Math.sin(waterBase[i]*1.7+S.anim*1.4)*.028+Math.sin(waterBase[i+2]*1.1-S.anim*2)*.033;water.geometry.attributes.position.needsUpdate=true;
 for(const f of ripples){f.position.z+=dt*(.5+LEVELS[S.level].flow);if(f.position.z>14.8)f.position.z=-14.8;f.material.opacity=.43;}
 for(const c of clouds){c.position.x+=dt*.1;if(c.position.x>43)c.position.x=-43;}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.v.y-=dt*4;p.mesh.position.addScaledVector(p.v,dt);p.mesh.rotation.x+=dt*3;p.mesh.scale.setScalar(Math.max(0,p.life/p.max));if(p.life<=0){world.remove(p.mesh);p.mesh.geometry.dispose();particles.splice(i,1)}}
 marker.scale.setScalar(1+Math.sin(S.anim*6)*.09);for(const b of bridges)for(const p of b.parts)if(!p.built)p.ghost.children[0].material.opacity=S.mode==='build'?.3+Math.sin(S.anim*2)*.1:.13;
 if(S.rain&&Math.random()<.6){const x=rand(-18,18),z=rand(-14,14);const m=box(.022,.25,.022,mat(0xe7f0df,{transparent:true,opacity:.55}),x,rand(5,8),z);m.castShadow=false;particles.push({mesh:m,v:new THREE.Vector3(-.3,-9,.5),life:.6,max:1})}
 if(performance.now()>toastUntil)$('#toast').classList.remove('visible');if(S.anim-lastUi>.18){updateUi();renderLabels();lastUi=S.anim;}renderer.render(scene,camera);}

function worldPoint(e){const rect=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);return raycaster.ray.intersectPlane(plane,p3)?.clone()}
function clickWorld(e){if(S.paused||S.finished)return;const p=worldPoint(e);if(!p)return;let closest=null,best=2;for(const n of nodes){const d=dist(p,n);if(d<best){best=d;closest=n}}if(S.mode==='gather'&&closest){gather(closest);return}
 const b=nearestBridge(p);if(['build','reinforce','repair'].includes(S.mode)&&Math.abs(p.z-b.z)<2.1&&Math.abs(p.x)<6){const part=b.parts.reduce((a,c)=>Math.abs(c.x-p.x)<Math.abs(a.x-p.x)?c:a);actBridge(b,S.mode,part);return}
 if(S.mode==='move'){const a=actors.find(a=>a.state==='waiting'&&dist(a.mesh.position,p)<.9);if(a){toast(`${SPECIES[a.type].name}：${SPECIES[a.type].weight===2?'我需要加固的桥，按 F 带我回家吧！':'桥通后，按 F 带我回家吧！'}`);return}}
 setTarget(p);}
function bind(){window.addEventListener('resize',resize);const canvas=renderer.domElement;canvas.addEventListener('pointerdown',e=>{pointerStart={x:e.clientX,y:e.clientY,yaw};dragged=false;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!pointerStart)return;const dx=e.clientX-pointerStart.x;if(Math.hypot(dx,e.clientY-pointerStart.y)>8){dragged=true;yaw=pointerStart.yaw-dx*.005;updateCamera();renderLabels();}});canvas.addEventListener('pointerup',e=>{if(!dragged)clickWorld(e);pointerStart=null});canvas.addEventListener('pointercancel',()=>pointerStart=null);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=clamp(zoom-e.deltaY*.001,0.7,1.7);resize()},{passive:false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
 window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='Tab'&&S.modal){const items=[...$('#modal').querySelectorAll('button:not(:disabled),[href],input')];if(items.length){const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}const k=e.key.toLowerCase();if(k==='escape'){if(S.modal&&S.modal!=='intro'&&S.modal!=='result')dismissModal();else if(!S.modal)showPause();return}if(S.modal)return;keys.add(k);if(e.repeat)return;if(k==='e')interact();if(k==='b'&&!S.paused)actBridge(nearestBridge(player.position),'build');if(k==='r'&&!S.paused)actBridge(nearestBridge(player.position),'repair');if(k==='f')escort();if(k==='h')showHelp();if(k==='v')toggleView();if('12345'.includes(k))setMode(['move','gather','build','reinforce','repair'][Number(k)-1]);});
 window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();if(S.started&&!S.finished&&!S.paused)showPause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(S.started&&!S.finished&&!S.paused)showPause()}});
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#escortBtn').onclick=escort;$('#helpBtn').onclick=showHelp;$('#pauseBtn').onclick=()=>{if(S.modal==='pause')closeModal();else showPause()};$('#mapBtn').onclick=showMap;$('#upgradeBtn').onclick=()=>showUpgrades();$('#viewBtn').onclick=toggleView;$('#soundBtn').onclick=()=>{saved.sound=!saved.sound;save();updateUi();if(saved.sound){initAudio();sound('start');toast('森林的声音已开启')}else toast('声音已关闭')};$('#touchAction').onclick=interact;
 for(const btn of document.querySelectorAll('[data-dir]')){const k={up:'w',left:'a',down:'s',right:'d'}[btn.dataset.dir];btn.addEventListener('pointerdown',e=>{e.preventDefault();if(S.paused)return;btn.setPointerCapture(e.pointerId);keys.add(k)});['pointerup','pointercancel','lostpointercapture'].forEach(event=>btn.addEventListener(event,()=>keys.delete(k)));}
}
function toggleView(){viewTop=!viewTop;updateCamera();renderLabels();toast(viewTop?'俯瞰视角 · 拖动仍可旋转':'回到林间视角')}
let audioContext=null;
function initAudio(){if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();}
function sound(type){if(!saved.sound)return;try{initAudio();const tunes={gather:[420,620],build:[230,350,470],success:[523,659,784,1046],warn:[260,220],whistle:[700,920,850],start:[392,523,659]};(tunes[type]||[440]).forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type==='build'?'triangle':'sine';o.frequency.value=f;o.connect(g);g.connect(audioContext.destination);const t=audioContext.currentTime+i*.095;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.28);o.start(t);o.stop(t+.3)})}catch{}}

// Readable state and shared actions support diagnostics and the browser's optional WebMCP API.
function getState(){return {level:S.level+1,title:LEVELS[S.level].name,started:S.started,paused:S.paused,finished:S.finished,mode:S.mode,wood:S.wood,stone:S.stone,coins:S.coins,energy:Math.round(S.energy),time:Math.round(S.time),rescued:S.rescued,total:actors.length,player:{x:Number(player.position.x.toFixed(2)),z:Number(player.position.z.toFixed(2))},bridges:bridges.map(b=>({lane:b.index+1,built:b.parts.filter(p=>p.built).length,reinforced:b.parts.filter(p=>p.built&&p.strength===2).length,durability:b.parts.map(p=>p.built?Math.round(p.hp):0)})),animals:actors.map(a=>({type:a.type,state:a.state})),upgrades:{...saved.upgrades},stars:[...saved.stars]};}
window.beaverGame={getState};
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;try{const lifecycle=new AbortController();const register=tool=>Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});register({name:'get_beaver_creek_state',title:'查看溪谷进度',description:'Read current resources, rescue progress, bridge condition, and equipment in Beaver Creek.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>getState()});register({name:'select_beaver_tool',title:'选择海狸工具',description:'Select the visible movement, gathering, bridge building, reinforcement, or repair tool.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['move','gather','build','reinforce','repair']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['move','gather','build','reinforce','repair'].includes(input.mode))throw new Error('Invalid tool mode');setMode(input.mode);return {mode:S.mode}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
try{setup();registerTools()}catch(error){console.error(error);const loading=$('#loading');loading.innerHTML='<div class="loading-beaver">🦫</div><h2>溪谷暂时没有打开</h2><p>请启用浏览器硬件加速后刷新，再来见见阿木。</p><button class="primary" onclick="location.reload()">重新打开</button>';}
